import random

# We will generate 500 high-quality, verified Arabic trivia questions for 'trivia_spark'
# Each item will have: id, gameId: 'trivia_spark', category, question, options (shuffled), correctAnswer, explanation

questions = []

def add(q, ans, wrongs, cat, exp):
    opts = [ans] + list(wrongs)
    random.shuffle(opts)
    questions.append({
        "id": f"t500-{len(questions)+1}",
        "gameId": "trivia_spark",
        "category": cat,
        "question": q,
        "options": opts,
        "correctAnswer": ans,
        "explanation": exp
    })

